function l(n,t,e,i){const s=a=>a*Math.PI/180,r=s(e-n),o=s(i-t),f=Math.sin(r/2)**2+Math.cos(s(n))*Math.cos(s(e))*Math.sin(o/2)**2;return 2*6371e3*Math.asin(Math.sqrt(f))}function m(n,t,e){const[i,c]=n,[s,r]=t,[o,f]=e,a=o-s,u=f-r,M=a*a+u*u;if(M===0)return t;let h=((i-s)*a+(c-r)*u)/M;return h=Math.max(0,Math.min(1,h)),[s+h*a,r+h*u]}function g(n,t){if(!t||t.length<2)return null;let e=1/0,i=0,c=0;for(let s=0;s<t.length-1;s++){const r=t[s],o=t[s+1],f=l(r[0],r[1],o[0],o[1]),a=m(n,r,o),u=l(n[0],n[1],a[0],a[1]);u<e&&(e=u,i=c+l(r[0],r[1],a[0],a[1])),c+=f}return{distanceToRoute:e,distanceCovered:i,totalRouteLength:c}}function x(n,t){const[e,i]=n;let c=!1;for(let s=0,r=t.length-1;s<t.length;r=s++){const o=t[s][0],f=t[s][1],a=t[r][0],u=t[r][1];o>e!=a>e&&i<(u-f)*(e-o)/(a-o)+f&&(c=!c)}return c}function d(n,t){let e=1/0;for(let i=0;i<t.length;i++){const c=t[i],s=t[(i+1)%t.length],r=m(n,c,s),o=l(n[0],n[1],r[0],r[1]);o<e&&(e=o)}return e}function D(n){if(n==null||!isFinite(n)||n<0)return"—";const t=Math.floor(n/3600),e=Math.round(n%3600/60);return t===0?`${e} min`:`${t}h ${e}min`}function R(n){if(!n)return"—";const t=Math.floor((new Date-n)/1e3);if(t<60)return"just now";const e=Math.floor(t/60);return e<60?`${e}m ago`:`${Math.floor(e/60)}h ${e%60}m ago`}function $(n,t){return n.getFullYear()===t.getFullYear()&&n.getMonth()===t.getMonth()&&n.getDate()===t.getDate()}export{x as a,d,D as f,l as h,$ as i,g as p,R as t};
